{"path": "dut.sv", "content": "module top_module (
    input  logic       wclk,
    input  logic       wrst_n,
    input  logic       wvalid,
    input  logic [7:0] wdata,
    output logic       wready,
    input  logic       rclk,
    input  logic       rrst_n,
    input  logic       rready,
    output logic       rvalid,
    output logic [7:0] rdata
);

    // ============================================================
    // 写时钟域信号
    // ============================================================
    logic [1:0] wptr_bin;        // 写指针（二进制，2位，容量4）
    logic [2:0] wptr_gray;       // 写指针（格雷码，3位）
    logic [2:0] wptr_gray_sync;  // 写指针格雷码同步到读时钟域
    logic [2:0] rptr_gray_sync;  // 读指针格雷码同步到写时钟域

    // ============================================================
    // 读时钟域信号
    // ============================================================
    logic [1:0] rptr_bin;        // 读指针（二进制，2位）
    logic [2:0] rptr_gray;       // 读指针（格雷码，3位）

    // ============================================================
    // 存储阵列
    // ============================================================
    logic [7:0] mem [0:3];

    // ============================================================
    // 复位同步释放
    // ============================================================
    logic wrst_n_sync;
    logic rrst_n_sync;

    // 写时钟域复位同步释放
    always_ff @(posedge wclk or negedge wrst_n) begin
        if (!wrst_n)
            wrst_n_sync <= 1'b0;
        else
            wrst_n_sync <= 1'b1;
    end

    // 读时钟域复位同步释放
    always_ff @(posedge rclk or negedge rrst_n) begin
        if (!rrst_n)
            rrst_n_sync <= 1'b0;
        else
            rrst_n_sync <= 1'b1;
    end

    // ============================================================
    // 写指针逻辑
    // ============================================================
    always_ff @(posedge wclk or negedge wrst_n) begin
        if (!wrst_n) begin
            wptr_bin <= 2'b00;
        end else if (wvalid && wready) begin
            wptr_bin <= wptr_bin + 2'b01;
        end
    end

    // 二进制转格雷码
    assign wptr_gray = {wptr_bin[1], wptr_bin[1] ^ wptr_bin[0], wptr_bin[0]};

    // ============================================================
    // 读指针逻辑
    // ============================================================
    always_ff @(posedge rclk or negedge rrst_n) begin
        if (!rrst_n) begin
            rptr_bin <= 2'b00;
        end else if (rvalid && rready) begin
            rptr_bin <= rptr_bin + 2'b01;
        end
    end

    // 二进制转格雷码
    assign rptr_gray = {rptr_bin[1], rptr_bin[1] ^ rptr_bin[0], rptr_bin[0]};

    // ============================================================
    // 跨时钟域同步（两级同步器）
    // ============================================================

    // 写指针格雷码同步到读时钟域
    logic [2:0] wptr_gray_sync_1;
    always_ff @(posedge rclk or negedge rrst_n) begin
        if (!rrst_n) begin
            wptr_gray_sync_1 <= 3'b000;
            wptr_gray_sync   <= 3'b000;
        end else begin
            wptr_gray_sync_1 <= wptr_gray;
            wptr_gray_sync   <= wptr_gray_sync_1;
        end
    end

    // 读指针格雷码同步到写时钟域
    logic [2:0] rptr_gray_sync_1;
    always_ff @(posedge wclk or negedge wrst_n) begin
        if (!wrst_n) begin
            rptr_gray_sync_1 <= 3'b000;
            rptr_gray_sync   <= 3'b000;
        end else begin
            rptr_gray_sync_1 <= rptr_gray;
            rptr_gray_sync   <= rptr_gray_sync_1;
        end
    end

    // ============================================================
    // 满/空判断
    // ============================================================
    logic wfull;
    logic rempty;

    // 写满：写指针和读指针（同步后）格雷码最高两位相反，其余位相同
    assign wfull = (wptr_gray[2] != rptr_gray_sync[2]) &&
                   (wptr_gray[1] != rptr_gray_sync[1]) &&
                   (wptr_gray[0] == rptr_gray_sync[0]);

    // 读空：写指针和读指针（同步后）格雷码完全相同
    assign rempty = (wptr_gray_sync == rptr_gray);

    // ============================================================
    // 输出信号
    // ============================================================
    assign wready = !wfull && wrst_n_sync;
    assign rvalid = !rempty && rrst_n_sync;

    // 读数据：非空时输出队首数据，空时输出0
    always_comb begin
        if (rvalid)
            rdata = mem[rptr_bin];
        else
            rdata = 8'b0;
    end

    // ============================================================
    // 写数据存储
    // ============================================================
    always_ff @(posedge wclk) begin
        if (wvalid && wready) begin
            mem[wptr_bin] <= wdata;
        end
    end

endmodule
"}

{"path": "diag_tb.sv", "content": "module tb(output reg done);

    logic wclk, wrst_n, wvalid, wready;
    logic [7:0] wdata;
    logic rclk, rrst_n, rready, rvalid;
    logic [7:0] rdata;

    top_module dut (
        .wclk(wclk), .wrst_n(wrst_n), .wvalid(wvalid), .wdata(wdata), .wready(wready),
        .rclk(rclk), .rrst_n(rrst_n), .rready(rready), .rvalid(rvalid), .rdata(rdata)
    );

    // independent clocks
    initial wclk = 0;
    always #5 wclk = ~wclk;   // 100MHz
    initial rclk = 0;
    always #7 rclk = ~rclk;   // ~71MHz

    // scoreboard
    logic [7:0] q[$];
    int wcnt, rcnt;

    task automatic wpush(input [7:0] d);
        wvalid <= 1; wdata <= d;
        // wait until accepted (pre-edge wvalid&&wready)
        do @(posedge wclk); while (!(wvalid && wready));
        wvalid <= 0;
        q.push_back(d);
        wcnt++;
    endtask

    task automatic rpop(input [7:0] exp);
        rready <= 1;
        do @(posedge rclk); while (!(rvalid && rready));
        rready <= 0;
        if (rdata !== exp) begin
            $display("FAIL: rdata=%h exp=%h", rdata, exp);
            $fatal(1, "data mismatch");
        end
        rcnt++;
    endtask

    initial begin
        done = 0;
        wvalid = 0; wdata = 0; rready = 0;
        wrst_n = 0; rrst_n = 0;
        repeat (5) @(posedge wclk);
        repeat (5) @(posedge rclk);
        wrst_n = 1; rrst_n = 1;
        // wait for sync release
        repeat (5) @(posedge wclk);
        repeat (5) @(posedge rclk);

        // empty check
        if (rvalid !== 0) $fatal(1, "rvalid not 0 after reset");
        if (rdata !== 0) $fatal(1, "rdata not 0 when empty");

        // push 4, pop 4, verify order
        wpush(8'h11);
        wpush(8'h22);
        wpush(8'h33);
        wpush(8'h44);
        rpop(8'h11);
        rpop(8'h22);
        rpop(8'h33);
        rpop(8'h44);

        // wrap test: push 6, pop 6
        wpush(8'hA1);
        wpush(8'hA2);
        wpush(8'hA3);
        wpush(8'hA4);
        wpush(8'hA5);
        wpush(8'hA6);
        rpop(8'hA1);
        rpop(8'hA2);
        rpop(8'hA3);
        rpop(8'hA4);
        rpop(8'hA5);
        rpop(8'hA6);

        // full/empty boundary: fill to full, verify wready drops
        wpush(8'hB1);
        wpush(8'hB2);
        wpush(8'hB3);
        wpush(8'hB4);
        // now full; wready should be 0
        repeat (3) @(posedge wclk);
        if (wready !== 0) $fatal(1, "wready not 0 when full");
        // drain
        rpop(8'hB1);
        rpop(8'hB2);
        rpop(8'hB3);
        rpop(8'hB4);

        repeat (3) @(posedge rclk);
        if (rvalid !== 0) $fatal(1, "rvalid not 0 after drain");

        $display("PASS: wcnt=%0d rcnt=%0d", wcnt, rcnt);
        done = 1;
    end

endmodule
"}

