{"path": "dut.sv", "content": "module top_module (input signed [15:0] product, output reg signed [7:0] y);
    reg signed [15:0] q;
    reg [6:0] rem;
    reg inc;
    reg signed [15:0] rounded;
    always @* begin
        q   = product >>> 7;
        rem = product[6:0];
        inc = (rem == 7'd64) ? q[0] : (rem > 7'd64);
        rounded = q + {{15{1'b0}}, inc};
        if (rounded > 16'sd127)
            y = 8'sd127;
        else if (rounded < -16'sd128)
            y = -8'sd128;
        else
            y = rounded[7:0];
    end
endmodule
"}

{"path": "diag_tb.sv", "content": "module tb(output reg done);
    reg signed [15:0] product;
    wire signed [7:0] y;
    top_module dut(.product(product), .y(y));

    integer errors;
    reg signed [15:0] p;
    reg signed [7:0] expect;

    task check(input signed [15:0] pv, input signed [7:0] ev);
        begin
            product = pv;
            #1;
            if (y !== ev) begin
                $display("FAIL product=%0d got=%0d expect=%0d", pv, y, ev);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        errors = 0;
        // exact halves: ties to even
        check(16'sd64, 8'sd0);      // 0.5 -> 0 (even)
        check(16'sd192, 8'sd2);     // 1.5 -> 2 (even)
        check(-16'sd64, 8'sd0);     // -0.5 -> 0 (even)
        check(-16'sd192, -8'sd2);   // -1.5 -> -2 (even)
        check(16'sd320, 8'sd2);     // 2.5 -> 2 (even)
        check(16'sd448, 8'sd4);     // 3.5 -> 4 (even)
        check(-16'sd320, -8'sd2);   // -2.5 -> -2 (even)
        check(-16'sd448, -8'sd4);   // -3.5 -> -4 (even)
        // non-half neighbors
        check(16'sd63, 8'sd0);
        check(16'sd65, 8'sd1);
        check(-16'sd63, 8'sd0);
