    reg clk, rst, s_valid, m_ready;
    reg [7:0] s_data;
    wire s_ready;
    wire m_valid;
    wire [7:0] m_data;

    top_module dut (
        .clk(clk), .rst(rst),
        .s_valid(s_valid), .s_data(s_data), .s_ready(s_ready),
        .m_valid(m_valid), .m_data(m_data), .m_ready(m_ready)
    );

    initial clk = 0;
    always #5 clk = ~clk;

    task automatic drive(input logic v, input logic [7:0] d, input logic r);
        @(negedge clk);
        s_valid = v; s_data = d; m_ready = r;
    endtask

    integer errs;
    initial begin
        errs = 0;
        s_valid = 0; s_data = 0; m_ready = 0;
        rst = 1;
        repeat (2) @(negedge clk);
        rst = 0;
        @(negedge clk);
        if (m_valid !== 0) begin $display("FAIL reset m_valid"); errs++; end

        // Offer A while downstream not ready: must be captured and held.
        drive(1, 8'hA1, 0);
        @(negedge clk); // sampling edge
        @(negedge clk); // after NBA
        if (m_valid !== 1) begin $display("FAIL A valid"); errs++; end
        if (m_data !== 8'hA1) begin $display("FAIL A data"); errs++; end

        // Blocked: change upstream data to B, must NOT overwrite held A.
        drive(1, 8'hB2, 0);
        @(negedge clk);
        @(negedge clk);
        if (m_valid !== 1) begin $display("FAIL hold valid"); errs++; end
        if (m_data !== 8'hA1) begin $display("FAIL hold data %h", m_data); errs++; end

        // Accept A.
        drive(1, 8'hB2, 1);
        @(negedge clk);
        @(negedge clk);
        if (m_valid !== 1) begin $display("FAIL accept valid"); errs++; end
        if (m_data !== 8'hB2) begin $display("FAIL accept data %h", m_data); errs++; end

        // Same-edge consume+receive: offer C while ready, replaces B.
        drive(1, 8'hC3, 1);
        @(negedge clk);
        @(negedge clk);
        if (m_valid !== 1) begin $display("FAIL turnover valid"); errs++; end
        if (m_data !== 8'hC3) begin $display("FAIL turnover data %h", m_data); errs++; end

        // Drain: no new data, ready high -> valid drops.
        drive(0, 8'h00, 1);
        @(negedge clk);
        @(negedge clk);
        if (m_valid !== 0) begin $display("FAIL drain valid"); errs++; end

        if (errs == 0) $display("PASS");
        else $display("FAIL %0d errors", errs);
        done = 1;
        if (errs != 0) $fatal(1, "diag failed");
    end
endmodule
"}

{"path": "dut.sv", "content": "module top_module #(
    parameter DEPTH = 3,
    parameter AW    = (DEPTH <= 1 ? 1 : $clog2(DEPTH)),
    parameter CW    = $clog2(DEPTH + 1)
) (
    input  logic        clk,
    input  logic        rst,
    input  logic        s_valid,
    input  logic [7:0]  s_data,
    output logic        s_ready,
    output logic        m_valid,
    output logic [7:0]  m_data,
    input  logic        m_ready,
    output logic [CW-1:0] count
);

    logic [7:0] mem [0:DEPTH-1];
    logic [AW-1:0] wptr, rptr;
    logic [CW-1:0] cnt;

    // Accepted transfers
    wire push = s_valid && s_ready;
    wire pop  = m_valid && m_ready;

    // Occupancy
    assign count   = cnt;
    assign m_valid = (cnt != 0);
    assign m_data  = m_valid ? mem[rptr] : 8'd0;

    // Ready: room exists, or a full slot is being freed by a pop this cycle.
    assign s_ready = (cnt < DEPTH) || (m_valid && m_ready);

    always_ff @(posedge clk) begin
        if (rst) begin
            wptr <= '0;
            rptr <= '0;
            cnt  <= '0;
        end else begin
            if (push) begin
                mem[wptr] <= s_data;
                wptr <= (wptr == AW'(DEPTH - 1)) ? '0 : wptr + 1'b1;
            end
            if (pop) begin
                rptr <= (rptr == AW'(DEPTH - 1)) ? '0 : rptr + 1'b1;
            end
            if (push && !pop)      cnt <= cnt + 1'b1;
            else if (!push && pop) cnt <= cnt - 1'b1;
        end
    end

endmodule
"}

