    localparam DEPTH = 3;
    localparam AW = (DEPTH <= 1 ? 1 : $clog2(DEPTH));
    localparam CW = $clog2(DEPTH + 1);

    reg clk = 0, rst = 0;
    reg s_valid = 0;
    reg [7:0] s_data = 0;
    reg m_ready = 0;
    wire s_ready, m_valid;
    wire [7:0] m_data;
    wire [CW-1:0] count;

