        .s_ready(s_ready), .m_valid(m_valid), .m_data(m_data),
        .m_ready(m_ready), .count(count)
    );

    always #5 clk = ~clk;

    integer errors = 0;
    integer i;

    task check(input int cond, input string msg);
        if (!cond) begin
            $display("FAIL: %s", msg);
            errors = errors + 1;
        end
    endtask

    initial begin
        // reset
        rst = 1;
        repeat (2) @(negedge clk);
        rst = 0;
        @(negedge clk);
        check(count == 0, "count after reset");
        check(m_valid == 0, "m_valid after reset");
        check(m_data == 0, "m_data empty");
        check(s_ready == 1, "s_ready empty");

        // push 3 items
        for (i = 0; i < 3; i = i + 1) begin
            s_valid = 1; s_data = 8'h10 + i;
            @(negedge clk);
            check(s_ready == 1, "s_ready during push");
        end
        s_valid = 0;
        @(negedge clk);
        check(count == 3, "count full");
        check(m_valid == 1, "m_valid full");
        check(m_data == 8'h10, "head data");

        // full: s_ready low when no pop
        check(s_ready == 0, "s_ready full no pop");

        // full replacement: pop + push same cycle
        m_ready = 1; s_valid = 1; s_data = 8'hAA;
        @(negedge clk);
        check(s_ready == 1, "s_ready full with pop");
        // after edge: head should be 0x11 (old head retired), count still 3
        check(count == 3, "count after replacement");
        check(m_data == 8'h11, "head after replacement");
        m_ready = 0; s_valid = 0;
        @(negedge clk);

        // drain
        m_ready = 1;
        @(negedge clk);
        check(m_data == 8'h12, "drain 2");
        @(negedge clk);
        check(m_data == 8'hAA, "drain replacement data");
        @(negedge clk);
        check(count == 0, "count empty after drain");
        check(m_valid == 0, "m_valid empty");
        check(m_data == 0, "m_data empty");
        m_ready = 0;

        if (errors == 0) $display("PASS");
        else $display("FAILED with %0d errors", errors);
        done = 1;
        if (errors != 0) $fatal(1, "diagnostic failed");
    end
endmodule
